struct pollfd fds[MAX];
/* fill fds[i].fd and .events = POLLIN for every connection */
int n = poll(fds, nfds, -1);          /* kernel scans all nfds */
for (int i = 0; i < nfds && n; i++)   /* user scans all again */
    if (fds[i].revents & POLLIN) { handle(fds[i].fd); n--; }

int ep = epoll_create1(0);
struct epoll_event ev = { .events = EPOLLIN | EPOLLET, .data.fd = conn };
epoll_ctl(ep, EPOLL_CTL_ADD, conn, &ev);        /* once per connection */
struct epoll_event ready[256];
int n = epoll_wait(ep, ready, 256, -1);          /* only ready FDs */
for (int i = 0; i < n; i++) drain_until_eagain(ready[i].data.fd);

struct io_uring ring; io_uring_queue_init(256, &ring, 0);
for (int i = 0; i < 64; i++) {
    struct io_uring_sqe *sqe = io_uring_get_sqe(&ring);
    io_uring_prep_read(sqe, fd, bufs[i], 4096, offsets[i]);
    sqe->user_data = i;
}
io_uring_submit(&ring);                    /* one syscall for 64 reads */
struct io_uring_cqe *cqe;
while (io_uring_wait_cqe(&ring, &cqe) == 0) { handle(cqe->user_data, cqe->res); io_uring_cqe_seen(&ring, cqe); }
